1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.RequiredFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request that is missing or blank in any required owner field,
13	 * before {@link BuildOwner} runs. The names of the offending fields are reported
14	 * as a 400 by {@link org.springframework.samples.petclinic.rest.escalation.RequiredFieldsExceptionHandler}.
15	 *
16	 * <p>This is a manual guard rather than {@code @Valid} so that a missing or blank
17	 * required field yields the {@code errors} field-name array this endpoint promises,
18	 * instead of the generic schema-validation problem detail.
19	 */
20	public class RequireOwnerFields {
21	
22	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
23	            throws RequiredFieldsException {
24	        List<String> errors = new ArrayList<>();
25	        checkField("firstName", request.getFirstName(), errors);
26	        checkField("lastName", request.getLastName(), errors);
27	        checkField("address", request.getAddress(), errors);
28	        checkField("city", request.getCity(), errors);
29	        checkField("telephone", request.getTelephone(), errors);
30	        if (!errors.isEmpty()) {
31	            throw new RequiredFieldsException(errors);
32	        }
33	        // Normalize the telephone: strip every non-digit, then require exactly 10 digits.
34	        String telephone = request.getTelephone().replaceAll("\\D", "");
35	        if (telephone.length() != 10) {
36	            throw new RequiredFieldsException(List.of("telephone"));
37	        }
38	        request.setTelephone(telephone);
39	        validated.set(request);
40	    }
41	
42	    private static void checkField(String name, String value, List<String> errors) {
43	        if (value == null || value.isBlank()) {
44	            errors.add(name);
45	        }
46	    }
47	}
