1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	import java.util.List;
4	
5	/**
6	 * Thrown when a create/update request is missing or blank in one or more required
7	 * fields. Carries the offending field names, which {@link RequiredFieldsExceptionHandler}
8	 * reports as a 400 with an {@code errors} array.
9	 */
10	public class RequiredFieldsException extends Exception {
11	
12	    private final List<String> errors;
13	
14	    public RequiredFieldsException(List<String> errors) {
15	        super("Missing or blank required fields: " + errors);
16	        this.errors = List.copyOf(errors);
17	    }
18	
19	    public List<String> getErrors() {
20	        return errors;
21	    }
22	}
