10		@Test
11		void coreRejectsDuplicateTelephone() throws Exception {
12			ObjectNode a = ownerNode();
13			createOwnerOk(a);
14			ObjectNode b = ownerNode();
15			b.put("telephone", a.get("telephone").asText());
16			createOwner(b).andExpect(status().isConflict());
